SELECT 
FROM eqp_repair
WHERE is_deleted = 0

    AND (repair_no LIKE CONCAT('%', #{keyword}, '%')
         OR reporter LIKE CONCAT('%', #{keyword}, '%'))


    AND equipment_id = #{equipmentId}


    AND status = #{status}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM eqp_repair WHERE is_deleted = 0
AND (repair_no LIKE CONCAT('%', #{keyword}, '%') OR reporter LIKE CONCAT('%', #{keyword}, '%'))
AND equipment_id = #{equipmentId}
AND status = #{status}
